package com.smartcanteen.entity;
import jakarta.persistence.*; import com.fasterxml.jackson.annotation.JsonIgnore; import java.math.BigDecimal;
@Entity @Table(name="order_items")
public class OrderItem { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @JsonIgnore @ManyToOne(fetch=FetchType.LAZY,optional=false) @JoinColumn(name="order_id",nullable=false) private CustomerOrder order; @ManyToOne(fetch=FetchType.EAGER) @JoinColumn(name="food_item_id") private FoodItem foodItem; @Column(nullable=false,length=120) private String foodNameSnapshot; @Column(nullable=false,precision=10,scale=2) private BigDecimal unitPrice; @Column(nullable=false) private int quantity; @Column(nullable=false,precision=10,scale=2) private BigDecimal lineTotal; public Long getId(){return id;} public CustomerOrder getOrder(){return order;} public void setOrder(CustomerOrder v){order=v;} public FoodItem getFoodItem(){return foodItem;} public void setFoodItem(FoodItem v){foodItem=v;} public String getFoodNameSnapshot(){return foodNameSnapshot;} public void setFoodNameSnapshot(String v){foodNameSnapshot=v;} public BigDecimal getUnitPrice(){return unitPrice;} public void setUnitPrice(BigDecimal v){unitPrice=v;} public int getQuantity(){return quantity;} public void setQuantity(int v){quantity=v;} public BigDecimal getLineTotal(){return lineTotal;} public void setLineTotal(BigDecimal v){lineTotal=v;} }
